create extension if not exists "pgcrypto";
create table if not exists households(id uuid primary key default gen_random_uuid(),name text not null default 'Idaman Sari',created_at timestamptz not null default now());
create table if not exists household_members(id uuid primary key default gen_random_uuid(),household_id uuid not null references households(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,display_name text not null check(display_name in('Rizal','Diyana')),role text not null default 'owner',unique(household_id,user_id));
create table if not exists categories(id uuid primary key default gen_random_uuid(),household_id uuid not null references households(id) on delete cascade,expense_type text not null check(expense_type in('One-time','Monthly')),main_category text not null,subcategory text not null,default_pic text not null check(default_pic in('Rizal','Diyana','Both')),active boolean not null default true,notes text,unique(household_id,expense_type,main_category,subcategory));
create table if not exists budgets(id uuid primary key default gen_random_uuid(),household_id uuid not null references households(id) on delete cascade,expense_type text not null check(expense_type in('One-time','Monthly')),main_category text not null,subcategory text not null,responsible_pic text not null check(responsible_pic in('Rizal','Diyana','Both')),planned_amount numeric(12,2) not null default 0,notes text,created_at timestamptz not null default now());
create table if not exists survey_items(id uuid primary key default gen_random_uuid(),household_id uuid not null references households(id) on delete cascade,survey_code text not null,survey_date date not null,item_type text not null,main_category text not null,subcategory text not null,description text not null,vendor text,contact text,option_model text,estimated_cost numeric(12,2) not null default 0,actual_cost numeric(12,2) not null default 0,product_link text,warranty_lead_time text,surveyed_by text not null check(surveyed_by in('Rizal','Diyana','Both')),rating int check(rating between 1 and 5),decision text not null default 'Considering' check(decision in('Considering','Shortlisted','Confirmed','Rejected')),confirmed_date date,paid_by text not null default 'Joint Account' check(paid_by in('Rizal','Diyana','Joint Account')),payment_method text,expense_status text not null default 'Planned' check(expense_status in('Planned','Quoted','Ordered','Pending','Paid','Cancelled')),rizal_pct numeric(5,2) not null default 50,diyana_pct numeric(5,2) not null default 50,notes text,created_at timestamptz not null default now(),check(rizal_pct+diyana_pct=100));
create table if not exists expenses(id uuid primary key default gen_random_uuid(),household_id uuid not null references households(id) on delete cascade,expense_code text not null,expense_date date not null,expense_type text not null check(expense_type in('One-time','Monthly')),main_category text not null,subcategory text not null,description text not null,vendor text,paid_by text not null check(paid_by in('Rizal','Diyana','Joint Account')),payment_method text,status text not null check(status in('Planned','Quoted','Ordered','Pending','Paid','Cancelled')),budgeted numeric(12,2) not null default 0,actual numeric(12,2) not null default 0,rizal_pct numeric(5,2) not null default 50,diyana_pct numeric(5,2) not null default 50,receipt_url text,notes text,survey_item_id uuid references survey_items(id) on delete set null,created_at timestamptz not null default now(),check(rizal_pct+diyana_pct=100));
create or replace function is_household_member(target_household uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from household_members where household_id=target_household and user_id=auth.uid())$$;
alter table households enable row level security;alter table household_members enable row level security;alter table categories enable row level security;alter table budgets enable row level security;alter table survey_items enable row level security;alter table expenses enable row level security;
create policy "members read household" on households for select using(is_household_member(id));
create policy "members read memberships" on household_members for select using(is_household_member(household_id));
create policy "members manage categories" on categories for all using(is_household_member(household_id)) with check(is_household_member(household_id));
create policy "members manage budgets" on budgets for all using(is_household_member(household_id)) with check(is_household_member(household_id));
create policy "members manage survey" on survey_items for all using(is_household_member(household_id)) with check(is_household_member(household_id));
create policy "members manage expenses" on expenses for all using(is_household_member(household_id)) with check(is_household_member(household_id));
insert into storage.buckets(id,name,public) values('house-documents','house-documents',false) on conflict(id) do nothing;
